mapper.delete:
DELETE FROM image
WHERE id = #{id}
  AND mime_type LIKE 'image/%'
  AND create_time < TIMESTAMPADD(HOUR, -#{retentionHours}, CURRENT_TIMESTAMP)
  AND NOT EXISTS (
    SELECT 1 FROM time_card tc WHERE tc.image_id = image.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM recipe r WHERE r.image_id = image.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM love_record_image lri WHERE lri.image_id = image.id
  )
